property.value:
(: factory method call :)
//PostfixUnaryExpression[pmd-kotlin:matchesSig('javax.xml.datatype.DatatypeFactory#newXMLGregorianCalendar(*)')]
|
(: property/field with XMLGregorianCalendar declared type (name-based: distinctive class name) :)
//PropertyDeclaration[
    (: isWithin pattern :)
    not(ancestor::FunctionBody or ancestor::LambdaLiteral)
    and .//T-Identifier[@Text='XMLGregorianCalendar']
]
|
(: function parameter typed as XMLGregorianCalendar :)
//FunctionValueParameter[.//T-Identifier[@Text='XMLGregorianCalendar']]

rule.example:
import javax.xml.datatype.XMLGregorianCalendar
import java.time.LocalDateTime

class Foo {
    private var cal: XMLGregorianCalendar? = null // bad
    fun good(dt: LocalDateTime): String = dt.toString() // good
}

property.value:
(: requires type info: kotlin-type-mapper auxClasspath :)
//PropertyDeclaration[
    (: isWithin pattern :)
    not(ancestor::FunctionBody or ancestor::LambdaLiteral)
    and (
        pmd-kotlin:typeIs('com.fasterxml.jackson.databind.ObjectMapper')
        or Expression//PrimaryExpression[
            pmd-kotlin:typeIs('com.fasterxml.jackson.databind.ObjectMapper')
        ]
    )
]

rule.example:
import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.databind.ObjectReader

class Foo {
    private val mapper: ObjectMapper = ObjectMapper() // bad
    private val reader: ObjectReader = ObjectMapper().readerFor(Any::class.java) // good
}

import com.fasterxml.jackson.databind.ObjectMapper

class Foo {
    companion object {
        private val MAPPER = ObjectMapper() // good
    }
    fun toJson(obj: Any): String {
        return ObjectMapper().writeValueAsString(obj) // bad
    }
}

property.value:
//PostfixUnaryExpression[
    (pmd-kotlin:matchesSig('com.google.gson.Gson#<init>(*)')
    or pmd-kotlin:matchesSig('com.google.gson.GsonBuilder#create()'))
    (: isWithin pattern :)
    and (ancestor::FunctionBody or ancestor::LambdaLiteral)
]

rule.example:
import com.google.gson.Gson

class Foo {
    companion object {
        private val GSON = Gson() // good
    }
    fun toJson(obj: Any): String {
        return Gson().toJson(obj) // bad
    }
}


import org.springframework.http.client.BufferingClientHttpRequestFactory
import org.springframework.http.client.ClientHttpRequestFactory

class Bad(delegate: ClientHttpRequestFactory) {
    val factory = BufferingClientHttpRequestFactory(delegate) // bad
}


import org.apache.http.HttpHost

class Bad {
    val host = HttpHost("hostname") // bad: no port specified
}

class Good {
    val host = HttpHost("hostname", 443, "https") // ok
}


import javax.xml.bind.JAXB
import javax.xml.transform.Source

class Bad {
    fun <T> unmarshal(src: Source, clazz: Class<T>): T = JAXB.unmarshal(src, clazz) // bad
}


import javax.xml.bind.JAXBContext

class Bad {
    fun marshal(obj: Any): String {
        val ctx = JAXBContext.newInstance(obj::class.java) // bad: recreated per call
        return ctx.createMarshaller().run { java.io.StringWriter().also { marshal(obj, it) }.toString() }
    }
}
class Good {
    companion object {
        private val CTX = JAXBContext.newInstance(Good::class.java) // ok: created once
    }
}
